-- Verified Crown Jewel CJ26. Idempotent catalogue-only append.
begin;
set local lock_timeout='5s';
lock table public.catalogue_sets,public.catalogue_subsets,public.catalogue_cards,public.catalogue_variants,public.catalogue_sources,public.catalogue_parallel_rules,public.collection_items,public.reference_images in share row exclusive mode;
create temporary table before_catalogue_sets on commit drop as select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end as row from public.catalogue_sets t;
create temporary table before_catalogue_subsets on commit drop as select case when t.set_id='2026-topps-now-wwe' and t.subset_code='POSTER' then to_jsonb(t)-'card_count' else to_jsonb(t) end as row from public.catalogue_subsets t;
create temporary table before_catalogue_cards on commit drop as select to_jsonb(t) as row from public.catalogue_cards t;
create temporary table before_catalogue_variants on commit drop as select to_jsonb(t) as row from public.catalogue_variants t;
create temporary table before_catalogue_sources on commit drop as select to_jsonb(t) as row from public.catalogue_sources t;
create temporary table before_catalogue_parallel_rules on commit drop as select to_jsonb(t) as row from public.catalogue_parallel_rules t;
create temporary table before_collection_items on commit drop as select to_jsonb(t) as row from public.collection_items t;
create temporary table before_reference_images on commit drop as select to_jsonb(t) as row from public.reference_images t;
do $$ begin
if (select count(*) from catalogue_cards where set_id='2026-topps-now-wwe') not in (136,137)
or (select count(*) from catalogue_variants where set_id='2026-topps-now-wwe') not in (183,186)
or exists(select 1 from catalogue_cards where set_id='2026-topps-now-wwe' and (card_number='CJ26' or checklist_order=137) and id<>'2026-TNWWE-POSTER-CJ26')
or exists(select 1 from catalogue_variants where set_id='2026-topps-now-wwe' and variant_order between 184 and 186 and card_id<>'2026-TNWWE-POSTER-CJ26')
then raise exception 'Unexpected annual NOW baseline'; end if;
end $$;
do $$ begin
 if exists(select 1 from public.catalogue_cards t join jsonb_populate_recordset(null::public.catalogue_cards,'[{"id":"2026-TNWWE-POSTER-CJ26","set_id":"2026-topps-now-wwe","checklist_order":137,"category":"Base","subset_code":"POSTER","card_number":"CJ26","display_name":"Crown Jewel","subject_1":"Crown Jewel","subject_2":null,"roster":null,"rookie":false,"parallel_group":"POSTER","image_status":"Missing","pricing_status":"Unpriced","source_url":"https://www.topps.com/products/crown-jewel-2026-wwe-topps-now-r-card-cj26","notes":"Official Topps product title identifies CJ26. US listing gives sale window 2026-10-30 to 2026-11-09 and shipping 7-10 business days after close. Final base print run and Rainbow quantity unpublished. Physical card-back code not independently inspected. Conditional Chrome/Opal editions excluded."}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.checklist_order is distinct from e.checklist_order or t.category is distinct from e.category or t.subset_code is distinct from e.subset_code or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.subject_1 is distinct from e.subject_1 or t.subject_2 is distinct from e.subject_2 or t.roster is distinct from e.roster or t.rookie is distinct from e.rookie or t.parallel_group is distinct from e.parallel_group or t.image_status is distinct from e.image_status or t.pricing_status is distinct from e.pricing_status or t.source_url is distinct from e.source_url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_cards row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_cards(id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes) select id,set_id,checklist_order,category,subset_code,card_number,display_name,subject_1,subject_2,roster,rookie,parallel_group,image_status,pricing_status,source_url,notes from jsonb_populate_recordset(null::public.catalogue_cards,'[{"id":"2026-TNWWE-POSTER-CJ26","set_id":"2026-topps-now-wwe","checklist_order":137,"category":"Base","subset_code":"POSTER","card_number":"CJ26","display_name":"Crown Jewel","subject_1":"Crown Jewel","subject_2":null,"roster":null,"rookie":false,"parallel_group":"POSTER","image_status":"Missing","pricing_status":"Unpriced","source_url":"https://www.topps.com/products/crown-jewel-2026-wwe-topps-now-r-card-cj26","notes":"Official Topps product title identifies CJ26. US listing gives sale window 2026-10-30 to 2026-11-09 and shipping 7-10 business days after close. Final base print run and Rainbow quantity unpublished. Physical card-back code not independently inspected. Conditional Chrome/Opal editions excluded."}]'::jsonb) on conflict do nothing;

do $$ begin
 if exists(select 1 from public.catalogue_variants t join jsonb_populate_recordset(null::public.catalogue_variants,'[{"id":"2026-TNWWE-POSTER-CJ26-IDENTITY","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":184,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Checklist identity","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-POSTER-CJ26-RAINBOW-FOIL-SHORT-PRINT","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":185,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Rainbow Foil Short Print","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-POSTER-CJ26-GOLD-SUPER-SHORT-PRINT","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":186,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Gold Super Short Print","serial_cap":26,"serial_exact":"/26","exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.card_id is distinct from e.card_id or t.variant_order is distinct from e.variant_order or t.subset is distinct from e.subset or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_variants row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_variants(id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from jsonb_populate_recordset(null::public.catalogue_variants,'[{"id":"2026-TNWWE-POSTER-CJ26-IDENTITY","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":184,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Checklist identity","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-POSTER-CJ26-RAINBOW-FOIL-SHORT-PRINT","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":185,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Rainbow Foil Short Print","serial_cap":null,"serial_exact":null,"exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"},{"id":"2026-TNWWE-POSTER-CJ26-GOLD-SUPER-SHORT-PRINT","set_id":"2026-topps-now-wwe","card_id":"2026-TNWWE-POSTER-CJ26","variant_order":186,"subset":"Event poster","card_number":"CJ26","display_name":"Crown Jewel","parallel":"Gold Super Short Print","serial_cap":26,"serial_exact":"/26","exclusive_note":null,"numbering_note":"Card-specific Topps product listing. Rainbow quantity and base print run unpublished.","verification_status":"Official Topps product listing"}]'::jsonb) on conflict do nothing;

do $$ begin
 if exists(select 1 from public.catalogue_sources t join jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-TNWWE-POSTER-CJ26-SOURCE","set_id":"2026-topps-now-wwe","source":"Topps official product page","purpose":"CJ26 identity and advertised editions","url":"https://www.topps.com/products/crown-jewel-2026-wwe-topps-now-r-card-cj26","notes":"Official Topps product title identifies CJ26. US listing gives sale window 2026-10-30 to 2026-11-09 and shipping 7-10 business days after close. Final base print run and Rainbow quantity unpublished. Physical card-back code not independently inspected. Conditional Chrome/Opal editions excluded."}]'::jsonb) e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources row; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from jsonb_populate_recordset(null::public.catalogue_sources,'[{"id":"2026-TNWWE-POSTER-CJ26-SOURCE","set_id":"2026-topps-now-wwe","source":"Topps official product page","purpose":"CJ26 identity and advertised editions","url":"https://www.topps.com/products/crown-jewel-2026-wwe-topps-now-r-card-cj26","notes":"Official Topps product title identifies CJ26. US listing gives sale window 2026-10-30 to 2026-11-09 and shipping 7-10 business days after close. Final base print run and Rainbow quantity unpublished. Physical card-back code not independently inspected. Conditional Chrome/Opal editions excluded."}]'::jsonb) on conflict do nothing;

update catalogue_subsets set card_count=16 where set_id='2026-topps-now-wwe' and subset_code='POSTER' and card_count=15;
update catalogue_sets set card_count=137,variant_count=186,updated_at=now() where id='2026-topps-now-wwe' and (card_count,variant_count)=(136,183);
do $$ begin
if (select count(*) from catalogue_cards where set_id='2026-topps-now-wwe')<>137
or (select count(*) from catalogue_variants where set_id='2026-topps-now-wwe')<>186
or (select count(*) from catalogue_cards where set_id='2026-topps-now-wwe' and subset_code='POSTER')<>16
or not exists(select 1 from catalogue_sets where id='2026-topps-now-wwe' and card_count=137 and variant_count=186)
or not exists(select 1 from catalogue_subsets where set_id='2026-topps-now-wwe' and subset_code='POSTER' and card_count=16)
then raise exception 'CJ26 count validation failed'; end if;
end $$;
do $$ begin if exists(select row from before_catalogue_sets except all select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end from public.catalogue_sets t) then raise exception 'Existing catalogue_sets rows changed'; end if; end $$;
do $$ begin if exists(select case when t.id='2026-topps-now-wwe' then to_jsonb(t)-'card_count'-'variant_count'-'updated_at' else to_jsonb(t) end from public.catalogue_sets t except all select row from before_catalogue_sets) then raise exception 'Unexpected catalogue_sets rows'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_subsets except all select case when t.set_id='2026-topps-now-wwe' and t.subset_code='POSTER' then to_jsonb(t)-'card_count' else to_jsonb(t) end from public.catalogue_subsets t) then raise exception 'Existing catalogue_subsets rows changed'; end if; end $$;
do $$ begin if exists(select case when t.set_id='2026-topps-now-wwe' and t.subset_code='POSTER' then to_jsonb(t)-'card_count' else to_jsonb(t) end from public.catalogue_subsets t except all select row from before_catalogue_subsets) then raise exception 'Unexpected catalogue_subsets rows'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t) then raise exception 'Existing catalogue_cards rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t) then raise exception 'Existing catalogue_variants rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t) then raise exception 'Existing catalogue_sources rows changed'; end if; end $$;
do $$ begin if exists(select row from before_catalogue_parallel_rules except all select to_jsonb(t) from public.catalogue_parallel_rules t) then raise exception 'Existing catalogue_parallel_rules rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.catalogue_parallel_rules t except all select row from before_catalogue_parallel_rules) then raise exception 'Unexpected catalogue_parallel_rules rows'; end if; end $$;
do $$ begin if exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t) then raise exception 'Existing collection_items rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items) then raise exception 'Unexpected collection_items rows'; end if; end $$;
do $$ begin if exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t) then raise exception 'Existing reference_images rows changed'; end if; end $$;
do $$ begin if exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images) then raise exception 'Unexpected reference_images rows'; end if; end $$;
select 'CJ26 verified' as result,(select count(*) from catalogue_cards) as cards,(select count(*) from collection_items) as collections;
commit;
